answer = ifScript();

function ifScript() {
	if(current.variables.isc_access_item_lc != ''){
		workflow.info(`Determining amount of items requested`);
		const access_items = current.variables.isc_access_item_lc.toString().split(',');
		if(access_items.length > 1){
			return 'yes';
		}
		if(access_items.length == 1){
			current.variables.isc_access_item = access_items[0];
			current.variables.isc_access_item_lc = '';
			return 'no';
		}
	}
	if(current.variables.isc_access_item != ''){
		return 'no';
	}
}

