// Set the variable 'answer' to '', 'approved' or 'rejected' to indicate the approval status for this approval.  When called, the following information is available:
//
//    counts.total = total number of users that are part of this approval
//    counts.approved = # of users that approved so far
//    counts.rejected = # of users that rejected so far
//    counts.requested = # of users that are pending approval
//    counts.not_requested = # of users that are not pending approval
//    counts.not_required = # of users that approval is not required
//

answer = [];

const access_item = new x_xal_idconnect.XalientUtilitiesCatalogItem().getAccessItemComposition(current.variables.isc_access_item.sailpoint_id.toString(),current.variables.isc_access_item.sailpoint_object_type.toString());
const identity = new x_xal_idconnect.XalientUtilitiesCatalogItem().getIdentity('id',access_item.owner.id);
const sn_user = new x_xal_idconnect.XalientUtilitiesCore().getSnUserAttribute('email',identity[0].emailAddress,'sys_id');
if(sn_user == current.variables.requested_for.sys_id.toString()){
	answer.push(current.variables.requested_for.manager);
}
else
	answer.push(sn_user);

