const identity = new x_xal_idconnect.XalientUtilitiesCatalogItem().getIdentity('email',current.variables.requested_for.email);
current.variables.identity_id = identity[0].id;

const gr_req = new GlideRecord('sc_request');
gr_req.get(current.request.sys_id);
gr_req.requested_for = current.variables.requested_for;
gr_req.update();
current.requested_for = current.variables.requested_for;

workflow.scratchpad.provisioning_status_checks++;
const res_request_status = new x_xal_idconnect.XalientUtilitiesCatalogItem().getAccessRequestStatus(current.variables.access_request_ids.toString());

try {
    if (res_request_status.getStatusCode() == 200) {
        const resb_request_status = JSON.parse(res_request_status.getBody());
		workflow.info(`Provisioning request status check - response body from request -\r\n\r\n${res_request_status.getBody()}`);
		activity.result = evaluateStates(resb_request_status);
    } else {
        throw `Error retrieving request status -\r\n\r\n
				Status Code - ${res_request_status.getStatusCode()}\r\n
				Server Response - \r\n\r\n ${res_request_status.getBody()}`;
    }
} catch (exception) {
	workflow.error(`Provisioning request status check - exception encountered -\r\n\r\n${exception}`);
	activity.result = 'processing_exception';
}

function evaluateStates(response) {
    const failureStates = new Set([
        "CANCELLED",
        "TERMINATED",
        "REJECTED",
        "PROVISIONING_FAILED",
        "NOT_ALL_ITEMS_PROVISIONED",
        "ERROR"
    ]);

    let allCompleted = true;

    for (const item of response) {
        const state = item.state;

        if (failureStates.has(state)) {
            return "provisioning_error";
        }

        if (state !== "REQUEST_COMPLETED") {
            allCompleted = false;
        }
    }
    if (!allCompleted && workflow.scratchpad.provisioning_status_checks > gs.getProperty('x_xal_idconnect.max_status_checks')) {
        return 'stalled';
    }

    return allCompleted ? "completed" : "in_progress";
}

